    67→  const {
    68→    children,
    69→    unstyled = false,
    70→    trimmed = false,
    71→    label,
    72→    icon,
    73→    kind = 'tertiary',
    74→    variant = 'normal',
    75→    disabled = false,
    76→    nonactive = false,
    77→    onPress,
    78→    asyncTimeout = 30_000,
